// Generates src/citation/styles.generated.ts: the bundled style packs as
// raw YAML text keyed by pack name. Committing the generated file keeps
// `tsc` and consumer installs working without a prebuild, while the script
// stays the source of truth for regeneration (npm run build re-runs it).
// The runtime reads this map instead of node:fs, so the Worker bundle
// carries no node builtins.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "citation", "styles");

const entries = readdirSync(dir)
  .filter((f) => f.endsWith(".yml"))
  .sort()
  .map((file) => {
    const name = file.replace(/\.yml$/, "");
    const yaml = readFileSync(join(dir, file), "utf8");
    // The text is emitted as a template literal; escape the three sequences
    // that would terminate or interpolate it.
    const escaped = yaml.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
    return `  ${JSON.stringify(name)}: \`${escaped}\``;
  });

const out = `// Generated by tools/gen-styles.mjs from src/citation/styles/*.yml —
// edit the YAML files and rebuild; do not edit this file.
export const BUNDLED_STYLE_SOURCES: Record<string, string> = {
${entries.join(",\n\n")},
};
`;

writeFileSync(join(dirname(dir), "styles.generated.ts"), out);
console.log(`styles.generated.ts: ${entries.length} pack(s)`);
